import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import AddCategories from "@/components/SloatBooking/Popups/AddCategories.vue";
import SnackBar from "@/components/SnackBar.vue";
import CreateResources from "@/components/SloatBooking/Popups/CreateResources.vue";
import ResourcesList from "@/components/SloatBooking/ResourcesList.vue";
import SlotCategories from "@/components/SloatBooking/SlotCategories.vue";
export default {
  components: {
    CreateResources,
    ResourcesList,
    SnackBar,
    SlotCategories,
    AddCategories
  },
  data: () => ({
    toggle_exclusive: "resources_slot",
    resourceCreation: false,
    categoriesAddition: false,
    componentCheck: 0,
    categoryKey: 0,
    resourcestKey: 0,
    SnackBarComponent: {},
    cardHeight: 0,
    adminAppExists: false
  }),
  mounted() {
    this.cardHeight = window.innerHeight - 140;
    this.fetch_admin_apps();
  },
  methods: {
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      const userapp = userObj.user_apps.find(app => app.dashboard_unique_type == "BOOKING_SLOT");
      // console.log(userapp, "userapp");
      if (userapp == undefined) {
        this.adminAppExists = false;
        return;
      }
      if (userapp.is_visible == false) {
        this.adminAppExists = false;
        return;
      }

      // Check if userObj and admin_apps exist
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "BOOKING_SLOT_ADMINS");
      this.adminAppExists = adminExists && (adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY") && adminExists.is_dashboard_admin === true;
    },
    back_call() {
      this.$router.push("/home/UserResources");
    },
    add_category() {
      this.componentCheck = 2;
      this.categoriesAddition = true;
    },
    categoryRefresh() {
      this.categoryKey += 1;
    },
    resource_Creation() {
      this.componentCheck = 1;
      this.resourceCreation = true;
    },
    userresource_refresh() {
      this.resourcestKey += 1;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.resourceCreation = false;
      this.categoriesAddition = false;
    }
  }
};
